#include <stdio.h>

void printArray(const int arr[], int size) {
    for(int i = 0; i < size; i++) {
        printf("Array element at index %d: %d\n", i, arr[i]);
    }
}

int main() {
    int numbers[5] = {10, 20, 30, 40, 50};
    printArray(numbers, 5);
    return 0;
}

#include <stdio.h>
#include <string.h>

void printChars(const char str[]) {
    int len = strlen(str);
    printf("First character: %c\n", str[0]);
    printf("Third character: %c\n", str[2]);
    printf("Last character: %c\n", str[len-1]);
}

int main() {
    char programName[] = "C-Program";
    printChars(programName);
    return 0;
}

#include <stdio.h>

int sumArray(const int arr[], int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) sum += arr[i];
    return sum;
}

int main() {
    int arr[5];
    for (int i = 0; i < 5; i++) {
        scanf("%d", &arr[i]);
    }
    int total = sumArray(arr, 5);
    printf("The sum of all array elements is: %d\n", total);
    return 0;
}

#include <stdio.h>

int findMax(const int arr[], int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

int main() {
    int arr[5];
    for (int i = 0; i < 5; i++) scanf("%d", &arr[i]);
    int maxVal = findMax(arr, 5);
    printf("The maximum element in the array is: %d\n", maxVal);
    return 0;
}

#include <stdio.h>

void printArray(const int arr[], int size) {
    for (int i = 0; i < size; i++) printf("%d%s", arr[i], i == size-1 ? "\n" : " ");
}

void reverseArray(int arr[], int size) {
    for (int i = 0, j = size-1; i < j; i++, j--) {
        int temp = arr[i]; arr[i] = arr[j]; arr[j] = temp;
    }
}

int main() {
    int arr[5];
    for (int i = 0; i < 5; i++) scanf("%d", &arr[i]);
    printf("Original array: "); printArray(arr, 5);
    reverseArray(arr, 5);
    printf("Reversed array: "); printArray(arr, 5);
    return 0;
}

#include <stdio.h>

int linearSearch(const int arr[], int size, int key) {
    for (int i = 0; i < size; i++) {
        if (arr[i] == key) return i;
    }
    return -1;
}

int main() {
    int arr[10], search_key;
    for (int i = 0; i < 10; i++) scanf("%d", &arr[i]);
    scanf("%d", &search_key);
    int idx = linearSearch(arr, 10, search_key);
    if (idx != -1) printf("Element found at index: %d\n", idx);
    else printf("Element not found\n");
    return 0;
}

#include <stdio.h>

int main() {
    int arr[10], freq[11] = {0};
    for (int i = 0; i < 10; i++) {
        scanf("%d", &arr[i]);
        freq[arr[i]]++;
    }
    printf("Frequency of elements:\n");
    for (int i = 1; i <= 10; i++) {
        if (freq[i] > 0)
            printf("%d appears %d time%s\n", i, freq[i], freq[i] == 1 ? "" : "s");
    }
    return 0;
}

#include <stdio.h>

int main() {
    int A[2][2], B[2][2], C[2][2];
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            scanf("%d", &A[i][j]);
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            scanf("%d", &B[i][j]);
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            C[i][j] = A[i][j] + B[i][j];
    printf("Resultant Matrix (A + B):\n");
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            printf("%d%s", C[i][j], j == 1 ? "\n" : " ");
        }
    }
    return 0;
}

