#include <stdio.h>

int main() {
    int scores[5][3];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 3; j++)
            scanf("%d", &scores[i][j]);
    printf("--- Student Totals ---\n");
    for (int i = 0; i < 5; i++) {
        int total = 0;
        for (int j = 0; j < 3; j++) total += scores[i][j];
        printf("Student %d Total: %d\n", i+1, total);
    }
    printf("\n--- Subject Averages ---\n");
    for (int j = 0; j < 3; j++) {
        int subject_total = 0;
        for (int i = 0; i < 5; i++) subject_total += scores[i][j];
        printf("Subject %d Average: %.2f\n", j+1, subject_total / 5.0);
    }
    return 0;
}
